#include <stdlib.h>
#include <string.h>
#include <threads.h>

struct counter_table
{
    mtx_t lock;
    int size;
    char words[256][32];
    int counts[256];
};

struct counter_table *table_new(void)
{
    struct counter_table *t = calloc(1, sizeof *t);
    if (t != NULL && mtx_init(&t->lock, mtx_plain) != thrd_success)
    {
        free(t);
        return NULL;
    }
    return t;
}

void table_free(struct counter_table *t)
{
    if (t == NULL) return;
    mtx_destroy(&t->lock);
    free(t);
}

static int find(struct counter_table *t, const char *word)
{
    for (int i = 0; i < t->size; i++)
        if (strncmp(t->words[i], word, 31) == 0) return i;
    return -1;
}

void table_add(struct counter_table *t, const char *word)
{
    mtx_lock(&t->lock);
    int i = find(t, word);
    if (i < 0 && t->size < 256)
    {
        i = t->size++;
        strncpy(t->words[i], word, 31);
        t->words[i][31] = '\0';
    }
    if (i >= 0) t->counts[i]++;
    mtx_unlock(&t->lock);
}

int table_get(struct counter_table *t, const char *word)
{
    mtx_lock(&t->lock);
    int i = find(t, word);
    int count = i >= 0 ? t->counts[i] : 0;
    mtx_unlock(&t->lock);
    return count;
}

int table_size(struct counter_table *t)
{
    mtx_lock(&t->lock);
    int size = t->size;
    mtx_unlock(&t->lock);
    return size;
}

struct text_job { struct counter_table *table; const char *text; };

static int count_text(void *arg)
{
    struct text_job *job = arg;
    const char *p = job->text;
    char word[32];
    while (*p)
    {
        while (*p == ' ') p++;
        size_t n = 0;
        while (p[n] && p[n] != ' ') n++;
        if (n > 0)
        {
            size_t keep = n < 31 ? n : 31;
            memcpy(word, p, keep);
            word[keep] = '\0';
            table_add(job->table, word);
        }
        p += n;
    }
    return 0;
}

int count_in_threads(struct counter_table *t, const char *const *texts, int n)
{
    thrd_t *ids = malloc((size_t)n * sizeof *ids);
    struct text_job *jobs = malloc((size_t)n * sizeof *jobs);
    int status = 0, started = 0;
    if (n > 0 && (ids == NULL || jobs == NULL)) { status = -1; goto done; }
    for (int i = 0; i < n; i++)
    {
        jobs[i] = (struct text_job){ t, texts[i] };
        if (thrd_create(&ids[i], count_text, &jobs[i]) != thrd_success) { status = -1; break; }
        started++;
    }
    for (int i = 0; i < started; i++) thrd_join(ids[i], NULL);
done:
    free(ids);
    free(jobs);
    return status;
}

unitTests:
TEST("one thread") { struct counter_table *t = table_new(); table_add(t, "cat"); table_add(t, "dog"); table_add(t, "cat"); CHECK_EQ(table_get(t, "cat"), 2); CHECK_EQ(table_get(t, "dog"), 1); CHECK_EQ(table_get(t, "eel"), 0); CHECK_EQ(table_size(t), 2); table_free(t); }
TEST("long words are cut") { struct counter_table *t = table_new(); table_add(t, "abcdefghijklmnopqrstuvwxyz0123456789"); CHECK_EQ(table_get(t, "abcdefghijklmnopqrstuvwxyz01234"), 1); table_free(t); }
TEST("many threads, nothing lost") { struct counter_table *t = table_new(); const char *texts[8]; for (int i = 0; i < 8; i++) texts[i] = "red green blue red red green the a an red"; CHECK_EQ(count_in_threads(t, texts, 8), 0); CHECK_EQ(table_get(t, "red"), 32); CHECK_EQ(table_get(t, "green"), 16); CHECK_EQ(table_get(t, "an"), 8); CHECK_EQ(table_size(t), 6); table_free(t); }
TEST("lots of repeats") { struct counter_table *t = table_new(); static char big[4][20001]; const char *texts[4]; for (int k = 0; k < 4; k++) { for (int i = 0; i < 10000; i++) { big[k][2 * i] = 'x'; big[k][2 * i + 1] = ' '; } big[k][20000] = '\0'; texts[k] = big[k]; } CHECK_EQ(count_in_threads(t, texts, 4), 0); CHECK_EQ(table_get(t, "x"), 40000); table_free(t); }

